import React from 'react';

import { DEFAULT_INDICATOR_COLOR } from './constants.js';
import {
  calculateAreaIndicatorPosition,
  calculateLineIndicatorPosition,
} from './util/calculate-indicator-position.js';
import { isAnnotationTotallyOutOfBounds } from './util/get-marker-position.js';
import { useCurrentTheme } from '../../../../core/hooks/useCurrentTheme.js';
import { AreaIndicator } from '../../../core/components/annotations-atoms/components/indicators/AreaIndicator.js';
import { LineIndicator } from '../../../core/components/annotations-atoms/components/indicators/LineIndicator.js';
import { getMarkerBrightnessBasedOnState } from '../../../core/components/annotations-atoms/functions/get-marker-brightness-based-on-state.js';
import { MarkerInteractionState } from '../../../core/components/annotations-atoms/types/marker.js';
import { BrightnessFilter } from '../../../core/components/BrightnessFilter.js';
import { SVGPlotLayout } from '../../../core/components/chart-grid/ChartGridRoot.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import {
  useAnnotationsHighlightedMarkers,
  useAnnotationsHoveredMarkers,
} from '../../hooks/store/selectors.js';
import { useHistogramAnnotationsConfig } from '../../hooks/useHistogramAnnotationsConfig.js';
import { useHistogramXScale } from '../../hooks/useHistogramXScale.js';
import { isHistogramValueAnnotation } from '../../types/histogram-annotations.js';

function defineIndicatorState(
  markerId: string,
  highlightedMarkersId: string[],
  hoveredMarkersIds: string[],
): MarkerInteractionState {
  if (highlightedMarkersId.includes(markerId)) {
    return 'active';
  }

  if (hoveredMarkersIds.includes(markerId)) {
    return highlightedMarkersId.length > 0 ? 'inactive' : 'hovered';
  }

  return 'default';
}

export const AnnotationsIndicators = () => {
  const highlightedMarkersId = useAnnotationsHighlightedMarkers();
  const hoveredMarkersIds = useAnnotationsHoveredMarkers();
  const { tracks } = useHistogramAnnotationsConfig();

  const { xScale } = useHistogramXScale();
  const { height } = useGridPlotSize();
  const theme = useCurrentTheme();

  const indicators = tracks.flatMap(
    ({
      markers,
      color: defaultTrackColor,
      indicatorsDisplay: trackIndicatorsDisplay,
    }) => {
      return markers.map(
        ({
          color,
          value,
          title,
          id: markerId,
          indicatorsDisplay: markerIndicatorsDisplay,
        }) => {
          const indicatorDisplay =
            markerIndicatorsDisplay ?? trackIndicatorsDisplay;
          const markerColor =
            color ?? defaultTrackColor ?? DEFAULT_INDICATOR_COLOR;

          const isNotHighlighted =
            !highlightedMarkersId.includes(markerId) &&
            !hoveredMarkersIds.includes(markerId);
          const state = defineIndicatorState(
            markerId,
            highlightedMarkersId,
            hoveredMarkersIds,
          );
          const slope = getMarkerBrightnessBasedOnState(theme, state);

          if (
            (isNotHighlighted && indicatorDisplay !== 'always') ||
            indicatorDisplay === 'never'
          ) {
            return null;
          }

          if (isAnnotationTotallyOutOfBounds(value, xScale)) {
            return null;
          }

          if (isHistogramValueAnnotation(value)) {
            const x = calculateLineIndicatorPosition(value, xScale);
            const brightnessFilterId = `brightness_${markerId}`;

            const filter = `url(#${brightnessFilterId})`;

            return (
              <>
                <BrightnessFilter id={brightnessFilterId} slope={slope} />
                <LineIndicator
                  key={x + title}
                  x={x}
                  color={markerColor}
                  height={height}
                  filter={filter}
                />
              </>
            );
          }

          const { x, width } = calculateAreaIndicatorPosition(value, xScale);
          const brightnessFilterId = `brightness_${markerId}`;

          const filter = `url(#${brightnessFilterId})`;

          return (
            <>
              <BrightnessFilter id={brightnessFilterId} slope={slope} />
              <AreaIndicator
                key={x + width + title}
                x={x}
                width={width}
                height={height}
                color={markerColor}
                filter={filter}
              />
            </>
          );
        },
      );
    },
  );

  return <SVGPlotLayout>{indicators}</SVGPlotLayout>;
};
